    country_ref.id, 'seoul', 'Seul', 'Seoul', 'Сеул',
    37.5665, 126.978, 9776000,
    'Seoul, officially Seoul Special Metropolitan City, is the capital and largest city of South Korea, and the largest city in the whole of Korea. The broader Seoul Metropolitan Area, encompassing Seoul, Gyeonggi Province and Incheon, emerged as the world''s sixth largest metropolitan economy in 2022, behind New York, Tokyo, Los Angeles, Paris, and London, and hosts more than half of South Korea''s population. Although Seoul''s population peaked at over 10 million, it has gradually decreased since 2014, standing at about 9.6 million residents as of 2024. Seoul is the seat of the South Korean government.', 'Seoul, officially Seoul Special Metropolitan City, is the capital and largest city of South Korea, and the largest city in the whole of Korea. The broader Seoul Metropolitan Area, encompassing Seoul, Gyeonggi Province and Incheon, emerged as the world''s sixth largest metropolitan economy in 2022, behind New York, Tokyo, Los Angeles, Paris, and London, and hosts more than half of South Korea''s population. Although Seoul''s population peaked at over 10 million, it has gradually decreased since 2014, standing at about 9.6 million residents as of 2024. Seoul is the seat of the South Korean government.',
    'wikipedia', 'https://en.wikipedia.org/wiki/Seoul', 'CC BY-SA', 'Wikipedia contributors, Seoul', now()
  from country_ref
  on conflict (country_id, slug) do update set
    name_az = excluded.name_az,
    name_en = excluded.name_en,
    name_ru = excluded.name_ru,
    lat = excluded.lat,
    lng = excluded.lng,
    population = excluded.population,
    short_desc_en = excluded.short_desc_en,
    description_en = excluded.description_en,
    source = excluded.source,
    source_url = excluded.source_url,
    license = excluded.license,
    attribution_text = excluded.attribution_text,
    last_synced_at = now()
  returning id, country_id
